-- In-memory fixture reproduces the existing hosted schema. No production data.
create role anon; create role authenticated;
create schema auth; create schema storage;
create table auth.users(id uuid primary key);
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
grant usage on schema public,auth,storage to anon,authenticated;
grant execute on function auth.uid() to anon,authenticated;
create table public.profiles(id uuid primary key references auth.users,full_name text,created_at timestamptz default now());
create table public.companies(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users,name text not null,role text not null check(role in ('shipper','agent','trucker')),verification_status text not null default 'pending',created_at timestamptz default now());
create table public.company_members(company_id uuid references public.companies,user_id uuid references auth.users,role text default 'owner',primary key(company_id,user_id));
create table public.rfqs(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users,company_id uuid references public.companies,service text not null,details jsonb not null default '{}',notes text default '',status text not null default 'open',awarded_bid_id uuid,created_at timestamptz default now());
create table public.bids(id uuid primary key default gen_random_uuid(),rfq_id uuid not null references public.rfqs,provider_id uuid not null references auth.users,company_id uuid not null references public.companies,currency text not null,amount numeric not null check(amount>0),transit_days integer not null check(transit_days>0),notes text default '',status text default 'submitted',created_at timestamptz default now());
alter table public.rfqs add constraint rfqs_awarded_bid_fk foreign key(awarded_bid_id) references public.bids(id);
create table public.platform_admins(user_id uuid primary key references auth.users);
create table public.messages(id uuid primary key default gen_random_uuid(),rfq_id uuid not null references public.rfqs,sender_id uuid not null references auth.users,recipient_id uuid not null references auth.users,body text not null check(length(trim(body)) between 1 and 4000),created_at timestamptz default now());
create table public.verification_requests(company_id uuid primary key references public.companies,submitted_by uuid not null references auth.users,registration_number text not null,contact_email text not null,contact_phone text not null,document_links text not null default '',details text not null default '',submitted_at timestamptz not null default now(),reviewed_at timestamptz);
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users,rfq_id uuid references public.rfqs,title text not null,body text default '',created_at timestamptz default now(),read_at timestamptz);
create function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.platform_admins where user_id=auth.uid())$$;
create function public.is_company_member(cid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.company_members where company_id=cid and user_id=auth.uid())$$;
create function public.owns_rfq(rid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.rfqs where id=rid and owner_id=auth.uid())$$;
create function public.has_bid_on_rfq(rid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.bids where rfq_id=rid and provider_id=auth.uid())$$;
create function public.notify_award() returns trigger language plpgsql security definer set search_path='' as $$begin if new.status='awarded' and old.status is distinct from 'awarded' then insert into public.notifications(user_id,rfq_id,title,body) select b.provider_id,new.id,'Quotation awarded','Your quotation was accepted' from public.bids b where b.id=new.awarded_bid_id;end if;return new;end$$;
create function public.notify_bid_created() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.notifications(user_id,rfq_id,title,body) select r.owner_id,r.id,'New freight quotation','A provider submitted a quote' from public.rfqs r where r.id=new.rfq_id;return new;end$$;
create function public.notify_message() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.notifications(user_id,rfq_id,title,body) values(new.recipient_id,new.rfq_id,'New RFQ message','You have a message');return new;end$$;
create trigger notify_award_trigger after update on public.rfqs for each row execute function public.notify_award();
create trigger notify_bid_created_trigger after insert on public.bids for each row execute function public.notify_bid_created();
create trigger notify_message_trigger after insert on public.messages for each row execute function public.notify_message();
alter table public.profiles enable row level security;alter table public.companies enable row level security;alter table public.company_members enable row level security;alter table public.rfqs enable row level security;alter table public.bids enable row level security;alter table public.messages enable row level security;alter table public.platform_admins enable row level security;alter table public.verification_requests enable row level security;alter table public.notifications enable row level security;
create policy "companies read" on public.companies for select to authenticated using(owner_id=auth.uid() or public.is_company_member(id) or verification_status='verified' or public.is_admin());
create policy "admins self" on public.platform_admins for select to authenticated using(user_id=auth.uid());
create policy "members read" on public.company_members for select to authenticated using(user_id=auth.uid());
create policy "rfqs create" on public.rfqs for insert to authenticated with check(owner_id=auth.uid() and status in ('draft','open') and (company_id is null or public.is_company_member(company_id)));
create policy "messages participants view" on public.messages for select to authenticated using(sender_id=auth.uid() or recipient_id=auth.uid());
create policy "messages participants send" on public.messages for insert to authenticated with check(sender_id=auth.uid() and sender_id<>recipient_id and ((public.owns_rfq(rfq_id) and exists(select 1 from public.bids b where b.rfq_id=messages.rfq_id and b.provider_id=messages.recipient_id)) or (public.has_bid_on_rfq(rfq_id) and exists(select 1 from public.rfqs r where r.id=messages.rfq_id and r.owner_id=messages.recipient_id))));
create policy "notifications own read" on public.notifications for select to authenticated using(user_id=auth.uid());
create policy "notifications own update" on public.notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "verification requests owner and admin read" on public.verification_requests for select to authenticated using(submitted_by=auth.uid() or public.is_admin());
create policy "verification requests owner edit" on public.verification_requests for update to authenticated using(submitted_by=auth.uid() and reviewed_at is null) with check(submitted_by=auth.uid() and reviewed_at is null);
grant select,insert,update,delete on all tables in schema public to authenticated;
create table storage.buckets(id text primary key,name text,public boolean,file_size_limit bigint,allowed_mime_types text[]);
create table storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text references storage.buckets,name text);
alter table storage.objects enable row level security;
create function storage.foldername(name text) returns text[] language sql as $$select (string_to_array(name,'/'))[1:array_length(string_to_array(name,'/'),1)-1]$$;
